function moment(r){const isExit=cursor===r.n+1,row=r.rows[Math.min(cursor,r.n)-1];$('cursorLabel').textContent=isExit?'SALIDA / M'+r.n:'MES '+String(cursor).padStart(2,'0');$('momentKicker').textContent=isExit?'FINAL DEL MES '+r.n:'MES '+String(cursor).padStart(2,'0')+' / '+r.n;const titles={1:'El proyecto arranca.',2:'El terreno es tuyo.',3:'Empieza la obra.'};$('momentTitle').textContent=isExit?(exit==='sell'?'Tu inversión regresa.':'Tu activo permanece.'):titles[cursor]||(cursor===r.n-2?'La obra está lista.':cursor>=r.n-1?'Preparamos la salida.':'El proyecto toma forma.');$('momentDescription').textContent=isExit?(exit==='sell'?'La venta liquida el crédito. El efectivo restante vuelve a ti.':'El nuevo crédito liquida el anterior. Conservas la propiedad para rentarla.'):(cursor===1?'Estructura de empresa, evaluación migratoria y preparación del desarrollo.':cursor===2?'Adquisición del lote y preparación para iniciar la construcción.':cursor===3?'Inicia la ejecución del presupuesto de construcción.':cursor>=r.n-1?'Comercialización y preparación del cierre.':'Obra en ejecución y aportaciones según el calendario del proyecto.');const cumulative=r.rows.slice(0,Math.min(cursor,r.n)).reduce((a,x)=>a+x.equity,0);$('momentMoney').className='moment-money';$('momentMoney').innerHTML=flow(isExit?(exit==='sell'?[['Recibes',r.net],['Aportaste',r.equity],['Utilidad',r.profit]]:[['Recuperas del refi',r.cashout],['Capital que permanece',r.retained],['Flujo mensual',r.cf]]):[['Tu aportación',row.equity],['Disposición bancaria',row.draw],['Tu capital acumulado',cumulative]]);}
function schedule(r){$('schedule').innerHTML='<table><thead><tr><th>Etapa</th><th>Tu capital</th><th>Banco</th><th>Interés</th><th>Regreso a ti</th></tr></thead><tbody>'+r.rows.map(x=>`<tr><td>Mes ${x.m}<small>${x.label}</small></td><td>${money(x.equity)}</td><td>${money(x.draw)}</td><td>${money(x.interest)}</td><td>—</td></tr>`).join('')+`<tr><td>Salida · final del mes ${r.n}</td><td>—</td><td>—</td><td>—</td><td>${money(exit==='sell'?r.net:r.cashout)}</td></tr></tbody></table>`;}
function wealth(r){let balance=r.loan,points=[s.sale-balance];for(let y=1;y<=5;y++){for(let m=0;m<12;m++)balance=Math.max(0,balance*(1+s.refRate/1200)-r.mortgage);points.push(s.sale*Math.pow(1+s.appreciation/100,y)-balance)}const min=Math.min(0,...points),max=Math.max(1,...points)*1.1,xx=i=>35+i*115,yy=v=>205-(v-min)/(max-min)*175;let path=points.map((v,i)=>(i?'L':'M')+xx(i)+','+yy(v)).join(' ');$('wealthChart').innerHTML=`<line class="axis" x1="35" y1="205" x2="610" y2="205"/><path d="${path} L610,205 L35,205 Z" fill="#657c5515"/><path d="${path}" fill="none" stroke="#617956" stroke-width="2.5"/>`+points.map((v,i)=>`<circle cx="${xx(i)}" cy="${yy(v)}" r="4" fill="#617956"/><text x="${xx(i)}" y="${yy(v)-13}" text-anchor="middle">${short(v)}</text><text x="${xx(i)}" y="232" text-anchor="middle">${i?'Año '+i:'Hoy'}</text>`).join('');$('wealthNumbers').innerHTML=`<span>Equity estimado año 5<b>${money(points[5])}</b></span><span>Flujo anual actual<b>${money(r.cf*12)}</b></span>`;}
function setExit(next){exit=next;document.querySelectorAll('[data-exit]').forEach(b=>{b.classList.toggle('active',b.dataset.exit===exit);b.setAttribute('aria-pressed',b.dataset.exit===exit)});$('sellContent').hidden=exit!=='sell';$('rentContent').hidden=exit!=='rent';render();}
function stop(){if(timer)clearInterval(timer);timer=null;$('play').textContent='▶';$('play').setAttribute('aria-label','Reproducir recorrido');}
document.addEventListener('input',e=>{let k=e.target.dataset.key;if(!k||fixed.has(k))return;if(e.target.type==='checkbox')s[k]=e.target.checked;else if(e.target.tagName==='SELECT')s[k]=e.target.value;else{if(e.target.value==='')return;const n=Number(e.target.value);if(!Number.isFinite(n))return;s[k]=Math.max(Number(e.target.min),Math.min(Number(e.target.max),n));if(e.target.type==='range'){const suffix=e.target.dataset.suffix;$('out-'+k).textContent=suffix==='USD'?money(s[k]):s[k].toLocaleString('en-US')+suffix;}}if(k==='months'){s.start=Math.min(s.start,s.months-2);$('start').value=s.start;$('start').max=s.months-2;}render();});document.addEventListener('change',e=>{const k=e.target.dataset.key;if(k&&e.target.type==='number')e.target.value=s[k]});document.addEventListener('click',e=>{const project=e.target.closest('[data-tier]'),choice=e.target.closest('[data-exit]');if(project){stop();s={...defaults,...presets[project.dataset.tier],tier:project.dataset.tier};cursor=1;mount();}if(choice)setExit(choice.dataset.exit);});$('monthCursor').oninput=e=>{stop();cursor=Number(e.target.value);const r=calc(s);drawJourney(r);moment(r)};$('journey').onclick=e=>{const m=e.target.closest('[data-month]');if(m){stop();cursor=Number(m.dataset.month);$('monthCursor').value=cursor;const r=calc(s);drawJourney(r);moment(r);}};$('journey').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}};$('play').onclick=()=>{if(timer){stop();return}if(cursor>=s.months+1)cursor=0;$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','Pausar recorrido');timer=setInterval(()=>{cursor++;$('monthCursor').value=cursor;const r=calc(s);drawJourney(r);moment(r);if(cursor>=r.n+1)stop();},800);};$('scheduleToggle').onclick=()=>{const hidden=$('schedule').hidden;$('schedule').hidden=!hidden;$('scheduleToggle').setAttribute('aria-expanded',hidden);$('scheduleToggle').textContent=hidden?'Ocultar cifras −':'Ver cifras por mes +'};const open=()=>{stop();$('settings').showModal();};$('openSettings').onclick=open;$('openMethod').onclick=open;$('closeSettings').onclick=()=>$('settings').close();$('doneSettings').onclick=()=>$('settings').close();$('reset').onclick=()=>{stop();s={...defaults,...presets[s.tier],tier:s.tier};cursor=1;mount();};mount();
